.radio-option input[type="radio"]:checked + label .radio-custom {
  border-color: var(--primary-color);
  background-color: var(--primary-color);
  box-shadow: inset 0 0 0 4px var(--bg-primary);
}

.radio-option input[type="radio"]:disabled + label {
  opacity: 0.5;
  cursor: not-allowed;
}

.radio-option input[type="radio"]:disabled + label .radio-custom {
  background-color: var(--border-color);
  border-color: var(--border-color);
}

.option-text {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
  flex: 1;
}

.option-label {
  display: block;
  font-weight: 500;
  color: var(--text-primary);
}

.option-description {
  display: block;
