(() => {
  'use strict';

  function initForm() {
    const form = document.getElementById('notificationForm');
    const successMessage = document.getElementById('successMessage');

    if (!form) return;

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const selectedValue = document.querySelector(
        'input[name="notification_preference"]:checked'
      )?.value;

      if (!selectedValue) {
        alert('Please select a notification preference');
        return;
      }

      // Show success message
      successMessage.setAttribute('aria-hidden', 'false');
      successMessage.focus();

      // Reset form after a brief delay
      setTimeout(() => {
        form.reset();
        successMessage.setAttribute('aria-hidden', 'true');
      }, 3000);

      // Log the selection (in a real app, this would send to a server)
      console.log('Notification preference saved:', selectedValue);
    });
  }

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initForm);
  } else {
    initForm();
  }
})();

